param([string]$Path,[switch]$SetAcl,[string]$Owner,[string]$AclSddl)
$ErrorActionPreference='Stop'
if(-not (Test-Path -LiteralPath $Path)){ New-Item -ItemType Directory -Path $Path -Force | Out-Null }
if($SetAcl){ if($AclSddl){ $acl=New-Object System.Security.AccessControl.DirectorySecurity; $acl.SetSecurityDescriptorSddlForm($AclSddl); Set-Acl -LiteralPath $Path -AclObject $acl } elseif($Owner){ $acl=Get-Acl -LiteralPath $Path; $acl.SetOwner([System.Security.Principal.NTAccount]$Owner); Set-Acl -LiteralPath $Path -AclObject $acl } }
Write-Output (Resolve-Path -LiteralPath $Path).Path

param([string]$NameLike)
$ErrorActionPreference='Stop'
$svcs=Get-Service | Where-Object { $_.Status -eq 'Running' }
if($NameLike){ $svcs=$svcs | Where-Object { $_.Name -like $NameLike -or $_.DisplayName -like $NameLike } }
$svcs | Select-Object Name,DisplayName,StartType,Status
